#pragma once

// Runtime support text compiled into every program generated by
// IrToOptCppEmitter. It mirrors the VM's observable behavior: the same fault
// messages (reported as `VM error: ...` with exit code 3), the same heap
// address encoding, the same file-handle packing and I/O error codes. The heap is
// the VM's own allocator (VmHeapCore) and string heap (VmTextHeap), pasted in between the two halves below, with the
// per-thread arenas (VmHeapArenas) after them: a program runs on arena 0, which is the VM's heap exactly until a
// second thread gets an arena.

namespace primec {

inline constexpr const char *OptCppRuntimeHeaders = R"CPP(#include <algorithm>
#include <bit>
#include <cerrno>
#include <charconv>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fcntl.h>
#include <string>
#include <string_view>
#include <iterator>
#include <map>
#include <mutex>
#include <new>
#include <set>
#include <sys/mman.h>
#include <unistd.h>
#include <utility>
#include <vector>

)CPP";

// Follows `namespace {` and VmHeapCoreSource (the emitter writes the host function
// declarations between OptCppRuntimeHeaders and the namespace, so they keep C linkage).
inline constexpr const char *OptCppRuntimePreamble = R"CPP(
constexpr uint64_t PsHeapTag = uint64_t{1} << 63;
constexpr uint64_t PsSlotBytes = 16;
constexpr unsigned PsMaxCallDepth = 4096;
constexpr uint32_t PsFileReadEof = 65536u;

// A live frame that can be addressed: its first local in the one numbering of all live locals the VM uses (the
// caller's base plus the caller's local count) and its slots.
struct PsFrameRef {
  uint64_t base;
  uint64_t count;
  uint64_t *slots;
};

struct Rt {
  int argc;
  char **argv;
  unsigned depth;
  // The heap and string heap of this thread's arena, and all the arenas of the program.
  VmHeapCore &heap;
  VmTextHeap &text;
  VmHeapArenas &arenas;
  // The base the next call's locals get, and the frames whose locals have addresses, innermost last.
  uint64_t localsTop = 0;
  unsigned frameCount = 0;
  PsFrameRef frames[PsMaxCallDepth + 1] = {};
};

[[noreturn]] void ps_fault(const char *message) {
  std::fflush(stdout);
  std::fprintf(stderr, "VM error: %s\n", message);
  std::fflush(stderr);
  std::exit(3);
}

[[noreturn]] void ps_fault(const std::string &message) {
  ps_fault(message.c_str());
}

struct PsString {
  const char *data;
  size_t size;
};

inline float ps_f32(uint64_t raw) { return std::bit_cast<float>(static_cast<uint32_t>(raw)); }
inline uint64_t ps_slot_f32(float value) { return static_cast<uint64_t>(std::bit_cast<uint32_t>(value)); }
inline double ps_f64(uint64_t raw) { return std::bit_cast<double>(raw); }
inline uint64_t ps_slot_f64(double value) { return std::bit_cast<uint64_t>(value); }
inline int64_t ps_s64(uint64_t value) { return static_cast<int64_t>(value); }

inline uint64_t ps_div_s64(uint64_t lhs, uint64_t rhs) {
  const int64_t divisor = ps_s64(rhs);
  if (divisor == 0) {
    ps_fault("division by zero in IR");
  }
  if (divisor == -1) {
    return uint64_t{0} - lhs;
  }
  return static_cast<uint64_t>(ps_s64(lhs) / divisor);
}

inline uint64_t ps_div_u64(uint64_t lhs, uint64_t rhs) {
  if (rhs == 0) {
    ps_fault("division by zero in IR");
  }
  return lhs / rhs;
}

inline void ps_emit(const char *text, size_t size, uint64_t flags) {
  FILE *out = (flags & 2) != 0 ? stderr : stdout;
  std::fwrite(text, 1, size, out);
  if ((flags & 1) != 0) {
    std::fputc('\n', out);
  }
}

inline void ps_emit(const std::string &text, uint64_t flags) {
  ps_emit(text.data(), text.size(), flags);
}

// ---- strings -------------------------------------------------------------

inline const PsString &ps_string(const PsString *table, size_t count, uint64_t index) {
  if (index >= count) {
    ps_fault("invalid string index in IR");
  }
  return table[static_cast<size_t>(index)];
}

// A static text argument of a host call: the module's NUL-terminated string.
inline const char *ps_host_text(const PsString *table, size_t count, uint64_t index) {
  return ps_string(table, count, index).data;
}

// ---- heap and indirect addressing ----------------------------------------

// Blocks of this thread's arena that other threads freed are freed before the next allocation.
inline void ps_heap_drain(Rt &rt) {
  if (rt.heap.threaded() && rt.heap.hasRemoteFrees()) [[unlikely]] {
    std::string error;
    if (!drainRemoteFrees(rt.text, rt.heap, error)) {
      ps_fault(error);
    }
  }
}

inline uint64_t ps_heap_alloc_bytes(Rt &rt, uint64_t count) {
  ps_heap_drain(rt);
  uint64_t address = 0;
  std::string error;
  if (!rt.heap.allocateBytes(count, address, error)) {
    ps_fault(error);
  }
  return address;
}

inline uint64_t ps_heap_alloc(Rt &rt, uint64_t count) {
  ps_heap_drain(rt);
  uint64_t address = 0;
  std::string error;
  if (!rt.heap.allocate(count, address, error)) {
    ps_fault(error);
  }
  return address;
}

inline void ps_heap_free(Rt &rt, uint64_t address) {
  std::string error;
  if (!rt.heap.release(address, error)) {
    ps_fault(error);
  }
}

inline uint64_t ps_heap_realloc(Rt &rt, uint64_t address, uint64_t count) {
  ps_heap_drain(rt);
  uint64_t fresh = 0;
  std::string error;
  if (!rt.heap.reallocate(address, count, fresh, error)) {
    ps_fault(error);
  }
  return fresh;
}

// The slot of local `index` (in the VM's numbering of all live locals) in an enclosing frame, or null.
// It only reads, and says so: see ps_resolve.
[[gnu::noinline, gnu::pure]] uint64_t *ps_resolve_outer(const Rt &rt, uint64_t index) {
  for (unsigned i = rt.frameCount; i-- > 0;) {
    const PsFrameRef &outer = rt.frames[i];
    if (index >= outer.base) {
      if (index - outer.base < outer.count) {
        return outer.slots + (index - outer.base);
      }
      break;
    }
  }
  return nullptr;
}

// Resolves a byte address to the slot it names: a tagged heap address, or a
// local of this frame (`base` is its first local) or of an enclosing one.
// The calls on its rare paths (a slot of another arena, a local of an enclosing frame) are of functions marked pure,
// so a loop need not read rt.heap again after one. Keep its five arguments: with a sixth, or with a local for the
// heap in every function, the compiler stopped inlining small functions and strings/append_chunks ran 19% more
// instructions.
inline uint64_t *ps_resolve(Rt &rt, uint64_t *frame, uint64_t base, size_t frameCount, uint64_t address) {
  if (VmHeapCore::isByteAddress(address)) {
    ps_fault("slot access to a byte region in IR: " + std::to_string(address));
  }
  if (address % PsSlotBytes != 0) {
    ps_fault("unaligned indirect address in IR: " + std::to_string(address));
  }
  if ((address & PsHeapTag) != 0) {
    uint64_t *slot = rt.heap.slotAt(address);
    if (slot == nullptr) {
      ps_fault("invalid indirect address in IR: " + std::to_string(address));
    }
    return slot;
  }
  const uint64_t index = address / PsSlotBytes;
  if (index - base < frameCount) {
    return &frame[static_cast<size_t>(index - base)];
  }
  uint64_t *slot = ps_resolve_outer(rt, index);
  if (slot == nullptr) {
    ps_fault("invalid indirect address in IR: " + std::to_string(address));
  }
  return slot;
}

[[noreturn]] void ps_byte_fault(uint64_t address) {
  if ((address & PsHeapTag) != 0 && !VmHeapCore::isByteAddress(address)) {
    ps_fault("byte access to a slot region in IR: " + std::to_string(address));
  }
  ps_fault("invalid byte address in IR: " + std::to_string(address));
}

// A byte address names a byte of a byte region; a slot address (a u8 local or slot field) names its
// slot's low byte.
// byteAt checks the tag bits itself, so a byte of a live region needs no other test.
// The check stays out of line: inlined into the byte loops of a large function, strings/append_chunks took
// 15% more CPU time (as TODO-5840 found too).
[[gnu::noinline]] uint8_t *ps_byte_at(Rt &rt, uint64_t address) {
  return rt.heap.byteAt(address);
}

inline uint64_t ps_load_u8(Rt &rt, uint64_t *frame, uint64_t base, size_t frameCount, uint64_t address) {
  if (const uint8_t *byte = ps_byte_at(rt, address)) {
    return *byte;
  }
  if (!VmHeapCore::isByteAddress(address)) {
    return *ps_resolve(rt, frame, base, frameCount, address) & UINT64_C(0xff);
  }
  ps_byte_fault(address);
}

inline uint64_t ps_store_u8(Rt &rt, uint64_t *frame, uint64_t base, size_t frameCount, uint64_t address,
                           uint64_t raw) {
  const uint8_t value = static_cast<uint8_t>(raw & UINT64_C(0xff));
  if (uint8_t *byte = ps_byte_at(rt, address)) {
    *byte = value;
    return value;
  }
  if (!VmHeapCore::isByteAddress(address)) {
    *ps_resolve(rt, frame, base, frameCount, address) = value;
    return value;
  }
  ps_byte_fault(address);
}

// ---- text across the host boundary ----------------------------------------

// A Text argument of a host call: the NUL-terminated bytes of a String's data block (0 is empty text) or
// a module-table literal.
inline const char *ps_host_text_arg(Rt &rt, const PsString *table, size_t count, uint64_t slot) {
  if (slot == 0) {
    return "";
  }
  if (VmHeapCore::isByteAddress(slot)) {
    const uint8_t *first = rt.heap.byteAt(slot);
    if (first == nullptr) {
      ps_fault("invalid text address passed to host function");
    }
    return reinterpret_cast<const char *>(first);
  }
  if ((slot & PsHeapTag) == 0 && slot < count) {
    return table[static_cast<size_t>(slot)].data;
  }
  ps_fault("invalid text passed to host function");
}

// A BytePointer argument: the `length` bytes at a byte-region address, all in one live region, or a fault (address 0
// with length 0 is null).
inline uint8_t *ps_host_bytes(Rt &rt, uint64_t address, uint64_t length) {
  if (address == 0 && length == 0) {
    return nullptr;
  }
  uint8_t *first = rt.heap.byteSpan(address, length);
  if (first == nullptr) {
    ps_fault("invalid byte pointer passed to host function");
  }
  return first;
}

// A Text result: the returned text copied into a fresh string-heap block the program owns (0 for empty).
inline uint64_t ps_host_text_result(Rt &rt, const char *text) {
  const size_t size = text == nullptr ? 0 : std::strlen(text);
  if (size == 0) {
    return 0;
  }
  uint64_t block = 0;
  std::string error;
  if (!rt.text.allocate(rt.heap, size + 1, block, error)) {
    ps_fault(error);
  }
  std::memcpy(rt.heap.byteAt(block), text, size);
  return block;
}

// The `__pstext_*` host functions the runtime answers itself.
inline uint64_t ps_text_call(Rt &rt, const char *name, const uint64_t *args) {
  uint64_t result = 0;
  bool known = false;
  std::string error;
  if (!callTextHostFunction(rt.text, rt.heap, name, args, result, known, error)) {
    ps_fault(error);
  }
  if (!known) {
    ps_fault(std::string("unknown text host function ") + name);
  }
  return result;
}

// `__pstext_literal`: the address of a module string literal's bytes (a byte region made on first use).
inline uint64_t ps_text_literal(Rt &rt, const PsString *table, size_t count, uint64_t index) {
  const PsString &literal = ps_string(table, count, index);
  uint64_t address = 0;
  std::string error;
  if (!rt.text.literal(rt.heap, index, count, literal.data, literal.size, address, error)) {
    ps_fault(error);
  }
  return address;
}

// `__pstext_argument`: the entry argument at the index copied into a fresh string-heap block.
inline uint64_t ps_text_argument(Rt &rt, uint64_t raw) {
  const int64_t index = static_cast<int32_t>(raw);
  const char *argument = index >= 0 && index < rt.argc ? rt.argv[index] : "";
  return ps_host_text_result(rt, argument);
}

// ---- argv ----------------------------------------------------------------

inline void ps_print_argv(Rt &rt, uint64_t rawIndex, uint64_t flags, bool unsafe) {
  const int64_t index = ps_s64(rawIndex);
  if (index < 0 || index >= rt.argc) {
    if (unsafe) {
      return;
    }
    ps_fault("invalid argv index in IR");
  }
  const char *text = rt.argv[index];
  ps_emit(text, std::strlen(text), flags);
}

// ---- files ---------------------------------------------------------------

inline uint32_t ps_io_error() {
  return errno == 0 ? 1u : static_cast<uint32_t>(errno);
}

inline uint64_t ps_pack_handle(int fd) {
  if (fd < 0) {
    return static_cast<uint64_t>(ps_io_error()) << 32;
  }
  return static_cast<uint64_t>(static_cast<uint32_t>(fd));
}

inline int ps_handle_fd(uint64_t handle) {
  return static_cast<int>(handle & 0xffffffffu);
}

// mode: 0 read, 1 write (create, truncate), 2 append (create).
inline uint64_t ps_file_open(const PsString &path, int mode) {
  const int flags = mode == 1 ? (O_WRONLY | O_CREAT | O_TRUNC) : (mode == 2 ? (O_WRONLY | O_CREAT | O_APPEND) : O_RDONLY);
  const std::string text(path.data, path.size);
  return ps_pack_handle(::open(text.c_str(), flags, 0644));
}

inline uint64_t ps_file_close(uint64_t handle) {
  return ::close(ps_handle_fd(handle)) < 0 ? static_cast<uint64_t>(ps_io_error()) : 0u;
}

inline uint64_t ps_file_flush(uint64_t handle) {
  return ::fsync(ps_handle_fd(handle)) < 0 ? static_cast<uint64_t>(ps_io_error()) : 0u;
}

inline uint64_t ps_file_read_byte(uint64_t handle, uint64_t &local) {
  uint8_t value = 0;
  const ssize_t rc = ::read(ps_handle_fd(handle), &value, 1);
  if (rc < 0) {
    return ps_io_error();
  }
  if (rc == 0) {
    return PsFileReadEof;
  }
  local = static_cast<uint64_t>(value);
  return 0;
}

inline uint64_t ps_write_all(uint64_t handle, const void *data, size_t size) {
  const char *cursor = static_cast<const char *>(data);
  size_t remaining = size;
  while (remaining > 0) {
    const ssize_t wrote = ::write(ps_handle_fd(handle), cursor, remaining);
    if (wrote < 0) {
      return ps_io_error();
    }
    if (wrote == 0) {
      return static_cast<uint64_t>(EIO);
    }
    remaining -= static_cast<size_t>(wrote);
    cursor += wrote;
  }
  return 0;
}

inline uint64_t ps_file_write_text(uint64_t handle, const std::string &text) {
  return ps_write_all(handle, text.data(), text.size());
}

inline uint64_t ps_file_write_byte(uint64_t handle, uint64_t raw) {
  const uint8_t value = static_cast<uint8_t>(raw & 0xffu);
  return ps_write_all(handle, &value, 1);
}

inline uint64_t ps_file_write_newline(uint64_t handle) {
  const char newline = '\n';
  return ps_write_all(handle, &newline, 1);
}

} // namespace

)CPP";

} // namespace primec
